def encode(s):
    out = []
    i = 0
    while i < len(s):
        j = i
        while j < len(s) and s[j] == s[i]:
            j += 1
        run = j - i
        out.append(s[i] if run == 1 else s[i] + str(run))
        i = j
    return "".join(out)


def decode(s):
    out = []
    i = 0
    while i < len(s):
        ch = s[i]
        i += 1
        j = i
        while j < len(s) and s[j].isdigit():
            j += 1
        run = int(s[i:j]) if j > i else 1
        out.append(ch * run)
        i = j
    return "".join(out)
